import { Component } from 'react'
import PropTypes from 'prop-types'
import { PkgDetailHeaderStyle } from './index.style'
import { DisplayFlexRCC } from '../../../../../../commonStyle/index.style'
import size from 'lodash/size'
import { CustomText } from '../../../../../../components'
import { AgentColorPallette } from '../../../../../../configs/colorPallete'
import get from 'lodash/get'

class PkgDetailHeader extends Component {
  static propTypes = {
    pkg: PropTypes.object
  }

  renderCardContentText = (content, weight, key) => (
    <CustomText
      color={AgentColorPallette.black}
      size='14px'
      weight={weight}
      lineHeight={1.5}
      key={key}
    >
      {content}
    </CustomText>
  )

  render () {
    const { pkg } = this.props
    const benefit = get(pkg, 'benefit', {})

    return (
      <PkgDetailHeaderStyle>
        <DisplayFlexRCC>
          <img src={get(pkg, 'logo_url', '')} width='180px' alt='' />
        </DisplayFlexRCC>
        <br />
        <div>
          {
            !!size(benefit.data) && benefit.data.map((item, index) => (
              <>
                {this.renderCardContentText(`${index + 1}. ${item.title}`, 800, `benefit_${index}`)}
                {this.renderCardContentText(item.sum_insured)}
                {(index + 1) !== size(benefit.data) && <br />}
              </>
            ))
          }
        </div>
      </PkgDetailHeaderStyle>
    )
  }
}

export default PkgDetailHeader
