export const currencyConverter = (amount, policy) => {
  const isCurrencyConversionRequired = policy.policy_detail.currency_label !== 'IDR'
  if (isCurrencyConversionRequired) {
    return getConvertedCurrency(amount, policy?.policy_detail.exchange_rate)
  }
  return amount
}

export const getCurrencyPrefix = (policy) => {
  const symbol = policy?.policy_detail?.currency_symbol || ''
  return symbol
}
export const getOtherCostForVehicle = (policy) => {
  const fees = (policy?.fees || []).map((fee) => ({
    name: fee?.label,
    amount: fee?.value,
    amountPrefix: fee?.currency === 'IDR' ? 'Rp ' : '',
  }))

  return [
    ...fees,
    {
      name: LANG_STRINGS.discountedPriceFromPartner,
      amount: policy.use_instalment
        ? currencyConverter(policy?.upcoming_instalment?.discount, policy)
        : currencyConverter(get(policy, 'discount', ''), policy),
      type: 'remove',
      amountPrefix: getCurrencyPrefix(policy),
      amountColor: '#fa6464',
    },
  ]
}

export const getBasicAccessoriesDetails = (policy) => {
  const accessories = get(policy, 'policy_detail.accessories', [])
  return accessories.map((accessory) => {
    return {
      ...accessory,
      amount: accessory.sum_insured,
    }
  })
}

export const getAddonsDetails = (policy) => {
  const addons = get(policy, 'product.add_ons', [])
  return addons.map((addon) => {
    return {
      ...addon,
      name: addon.add_on_name,
      amount: addon.premium,
    }
  })
}

