import { createRef, Component } from 'react'
import PropTypes from 'prop-types'
import { NotificationManager, NotificationContainer } from 'react-notifications'
import { PolicyHolderStyle } from './index.style'
import { connect } from 'react-redux'
import { Container, InnerForm, CustomText } from '../../../../components'
import { LANG_STRINGS, ERROR_LANG } from '../../../../lang'
import policyActions from '../../../../redux/policy/action'
import customerActions from '../../../../redux/customer/actions'
import { getParamsFromUri, getQueryParams } from '../../../../helpers/utility'
import { AgentColorPallette } from '../../../../configs/colorPallete'
import { getLippoPolicyHolderForm } from '../constants'
import { FlatBottomBtn, MitraCard } from '../../../../commonStyle/index.style'
import PkgDetailHeader from './components/PkgDetailHeader'
import isEmpty from 'lodash/isEmpty'
import { getDobFmt, prefixCountryCode } from '../../../../helpers/getPackageBody'
import addressActions from '../../../../redux/Address/actions'
import { find } from 'lodash/collection'
import { get as lodashGet } from 'lodash/object'
import { setToLocalStorage, getFromLocalStorageData } from '../../../../helpers/localstorage'
import { POLICY_DATA_KEY } from '../../../../constants/cookies'

const { getPackageDetail } = policyActions
const {
  createCustomerPolicy, resetCustomerStore,
  getCustomerPolicy, updateCustomerPolicyData
} = customerActions
const { getCities } = addressActions

class PolicyHolder extends Component {
  static propTypes = {
    prop: PropTypes
  }

  constructor (props) {
    super(props)
    this.pkgCode = getParamsFromUri.call(this, 'pkgCode')
    this.state = {
      productCode: this.pkgCode
    }
    this.policyHolderFormRef = createRef()
    this.finalData = getFromLocalStorageData(POLICY_DATA_KEY) || {}
    this.policyId = this.finalData.token || getParamsFromUri.call(this, 'id')
  }

  componentDidMount () {
    this.props.getPackageDetail({
      body: {},
      packageCode: this.pkgCode
    })
    this.props.getCities()
    if (this.policyId) {
      this.props.getCustomerPolicy(this.policyId)
    }
  }

  componentWillReceiveProps (nextProps) {
    const {
      createPolicyError, createPolicyMsg, createPolicyData,
      updateCustomerPolicyStatus, resetCustomerStore, updatePolicyError
    } = nextProps

    if (createPolicyError && createPolicyMsg && createPolicyMsg !== 'success') {
      NotificationManager.error(createPolicyMsg || ERROR_LANG.somethingWrong)
      resetCustomerStore(['creatCustomerPolicyStatus'])
    } else if (createPolicyMsg === 'success') {
      this.policyId = createPolicyData.id
      this.updateCustomerPolicy()
      resetCustomerStore(['creatCustomerPolicyStatus'])
    } else if (updateCustomerPolicyStatus === 'success') {
      if (this.pkgCode) {
        const id = this.policyId || createPolicyData.id
        this.props.history.push({
          pathname: `/${this.pkgCode}/policy/summary/${id}`
        })
      } else {
        this.props.history.push({
          pathname: `/covid/policy/${createPolicyData.id}/form`,
          state: {
            createPolicyData,
            ...this.props.location.state,
            policyHolderDetails: this.formData
          }
        })
      }
      resetCustomerStore(['creatCustomerPolicyStatus', 'customerPolicy', 'updateCustomerPolicyStatus'])
    } else if (updateCustomerPolicyStatus && updatePolicyError) {
      NotificationManager.error(updateCustomerPolicyStatus)
      resetCustomerStore(['updateCustomerPolicyStatus'])
    }
  }

  componentWillUnmount () {
    this.policyId = ''
  }

  handleContinue = async (e) => {
    // this action form
    const formData = await this.policyHolderFormRef.current.handleSubmit(e)
    const { citiesList } = this.props
    if (formData) {
      this.formData = formData
      this.finalData = {
        code: this.pkgCode,
        customer_data: {
          name: this.formData.name,
          email: this.formData.email,
          mobile_no: `${this.formData.mobile_no}`.startsWith('0') ? prefixCountryCode(this.formData.mobile_no) : `62-${this.formData.mobile_no}`
        },
        city: this.formData.city,
        city_name: find(citiesList, { id: this.formData.city }).display_name,
        dob: getDobFmt(this.formData.dob),
        gender: this.formData.gender,
        ktp_no: formData.ktp,
        agent_ref: getParamsFromUri.call(this, 'agentRef')
      }
      if (this.policyId) {
        this.updateCustomerPolicy()
      } else {
        this.createCustomerPolicy()
      }
    }
  }

  createCustomerPolicy = () => {
    // this is the basic details need to develop the
    this.props.createCustomerPolicy({
      ...this.finalData,
      leads_id: getQueryParams('tid') || ''
    })
  }

  updateCustomerPolicy = () => {
    this.finalData = {
      ...this.finalData,
      token: this.policyId
    }
    setToLocalStorage(POLICY_DATA_KEY, this.finalData)
    this.props.updateCustomerPolicyData(this.finalData)
  }

  render () {
    const {
      createPolicyLoader, validatePolicyLoader, customerPolicyLoader, customerPolicy,
      updateCustomerLoader, pkgDetailLoading, pkgDetail = {}, citiesList
    } = this.props
    const holderForm = getLippoPolicyHolderForm({
      ...(lodashGet(customerPolicy, 'customer_data', '')),
      ...(lodashGet(customerPolicy, 'policy_detail', '')),
      citiesList
    })
    return (
      <Container
        showInnerHeader
        hideBottomTabs
        title={LANG_STRINGS.contentsData}
        loader={
          pkgDetailLoading || createPolicyLoader || validatePolicyLoader ||
          customerPolicyLoader || updateCustomerLoader
        }
      >
        <PolicyHolderStyle>
          {
            !isEmpty(pkgDetail) && <PkgDetailHeader pkg={pkgDetail} />
          }
          <div className='policy-holder-content'>
            <CustomText
              color={AgentColorPallette.darkGold}
              size='16px'
              weight={800}
              bottom='20px'
            >
              {LANG_STRINGS.pleaseEnterPolicyHolderData}
            </CustomText>
            <MitraCard padding='20px' width='auto'>
              <InnerForm
                formData={holderForm}
                ref={this.policyHolderFormRef}
                className='holder-inner-form'
                border
              />
            </MitraCard>
          </div>
        </PolicyHolderStyle>
        <FlatBottomBtn
          bgColor={AgentColorPallette.primary}
          color={AgentColorPallette.darkerGold}
          onClick={(e) => this.handleContinue(e)}
        >
          {LANG_STRINGS.next}
        </FlatBottomBtn>
        <NotificationContainer />
      </Container>
    )
  }
}

export default connect(
  state => ({
    pkgDetail: state.Policy.packageDetail,
    citiesList: state.Address.citiesList,
    citiesLoading: state.Loading.GET_CITIES,
    pkgDetailLoading: state.Loading.GET_PACKAGE_DETAIL,
    createPolicyLoader: state.Loading.CUSTOMER_POLICY,
    customerPolicyLoader: state.Loading.GET_CUSTOMER_POLICY,
    updateCustomerLoader: state.Loading.UPDATE_CUSTOMER_POLICY,
    createPolicyError: state.Error.CUSTOMER_POLICY,
    updatePolicyError: state.Error.UPDATE_CUSTOMER_POLICY,
    createPolicyMsg: state.Customer.creatCustomerPolicyStatus,
    customerPolicy: state.Customer.customerPolicyData,
    createPolicyData: state.Customer.creatCustomerPolicy,
    updateCustomerPolicyStatus: state.Customer.updateCustomerPolicyStatus
  }),
  {
    getPackageDetail,
    getCities,
    resetCustomerStore,
    getCustomerPolicy,
    updateCustomerPolicyData,
    createCustomerPolicy
  }
)(PolicyHolder)
